PROGRAM BIW_WeldStationPLC
  VAR_INPUT
    CycleStart : BOOL;
    SafetyFenceOK : BOOL;
    inClampedOK : BOOL;
    inWeldDone : BOOL;
    inWeldCurrent : REAL;
  END_VAR
  VAR_OUTPUT
    outClampClose : BOOL := FALSE;
    outWeldStart : BOOL := FALSE;
    QualityFault : BOOL := FALSE;
  END_VAR

  IF NOT SafetyFenceOK THEN
    outClampClose := FALSE;
    outWeldStart := FALSE;
    QualityFault := FALSE;
  ELSE
    outClampClose := CycleStart;
    outWeldStart := CycleStart AND inClampedOK AND NOT inWeldDone;
    QualityFault := inWeldDone AND (inWeldCurrent < 9.5);
  END_IF;
END_PROGRAM

files.pid.c:
/* Clamped Discrete-Time PID Controller with Anti-Windup */

double pid_step(
    double kp,
    double ki,
    double kd,
    double out_min,
    double out_max,
    double *integral,
    double *prev_error,
    double setpoint,
    double measurement,
    double dt) {
  double error = setpoint - measurement;
  double p_term = kp * error;
  double next_integral = (*integral) + error * dt;
  double i_term = ki * next_integral;
  double d_term = 0.0;
  double raw_out = 0.0;
  double clamped_out = 0.0;

  if (dt > 1.0e-9) {
    d_term = kd * (error - (*prev_error)) / dt;
  }

  raw_out = p_term + i_term + d_term;
  clamped_out = raw_out;

  if (raw_out > out_max) {
    clamped_out = out_max;
  } else if (raw_out < out_min) {
    clamped_out = out_min;
  } else {
    *integral = next_integral;
  }

  *prev_error = error;
  return clamped_out;
}

files.biquad.c:
/* Second-Order Direct-Form II Transposed IIR Biquad Filter */

double biquad_process(
    double b0,
    double b1,
    double b2,
    double a1,
    double a2,
    double *z1,
    double *z2,
    double x) {
  double y = b0 * x + (*z1);
  double next_z1 = b1 * x - a1 * y + (*z2);
  double next_z2 = b2 * x - a2 * y;

  *z1 = next_z1;
  *z2 = next_z2;
  return y;
}

files.kalman.c:
#include "kalman.h"

void kalman_init(Kalman1D *kf, double pos0, double vel0, double q_proc, double r_meas) {
  kf->pos = pos0;
  kf->vel = vel0;
  kf->p00 = 1.0;
  kf->p01 = 0.0;
  kf->p10 = 0.0;
  kf->p11 = 1.0;
  kf->q_proc = q_proc;
  kf->r_meas = r_meas;
}

double kalman_update(Kalman1D *kf, double z_pos, double dt) {
  double pred_pos = kf->pos + kf->vel * dt;
  double pred_vel = kf->vel;

  double p00 = kf->p00 + dt * (kf->p10 + kf->p01) + dt * dt * kf->p11 + kf->q_proc;
  double p01 = kf->p01 + dt * kf->p11;
  double p10 = kf->p10 + dt * kf->p11;
  double p11 = kf->p11 + kf->q_proc;

  double innovation = z_pos - pred_pos;
  double s_cov = p00 + kf->r_meas;
  double k0 = p00 / s_cov;
  double k1 = p10 / s_cov;

  kf->pos = pred_pos + k0 * innovation;
  kf->vel = pred_vel + k1 * innovation;
  kf->p00 = (1.0 - k0) * p00;
  kf->p01 = (1.0 - k0) * p01;
  kf->p10 = p10 - k1 * p00;
  kf->p11 = p11 - k1 * p01;

  return kf->pos;
}

