files.pas.mod:
TITLE Passive Leak Membrane Conductance

NEURON {
  SUFFIX pas_leak
  NONSPECIFIC_CURRENT i
  RANGE g, e, i
}

PARAMETER {
  g = 0.0003 (S/cm2) <0, 1e9>
  e = -65.0 (mV)
}

ASSIGNED {
  v (mV)
  i (mA/cm2)
}

BREAKPOINT {
  i = g * (v - e)
}

files.alphasyn.mod:
TITLE Dual-Exponential Excitatory AMPA Synapse

NEURON {
  SUFFIX alpha_syn
  NONSPECIFIC_CURRENT i
  RANGE gmax, tau_r, tau_d, e, g, i
}

PARAMETER {
  gmax = 0.002 (uS) <0, 1e9>
  tau_r = 0.5 (ms) <0.01, 100>
  tau_d = 5.0 (ms) <0.1, 500>
  e = 0.0 (mV)
}

STATE {
  A
  B
}

ASSIGNED {
  v (mV)
  g (uS)
  i (nA)
}

INITIAL {
  A = 0.0
  B = 0.0
}

BREAKPOINT {
  SOLVE states METHOD cnexp
  g = gmax * (B - A)
  i = g * (v - e)
}

DERIVATIVE states {
  A' = -A / tau_r
  B' = -B / tau_d
}

files.cal_ghk.mod:
TITLE L-Type Calcium Channel with GHK Permeation

NEURON {
  SUFFIX cal_ghk
  USEION ca READ cai, cao WRITE ica
  RANGE pbar, gca, ica
  GLOBAL minf, hinf, mtau, htau
}

PARAMETER {
  pbar = 0.00015 (cm/s) <0, 1e9>
  cai = 0.0001 (mM)
  cao = 2.0 (mM)
  eca = 120.0 (mV)
}

STATE {
  m
  h
}

ASSIGNED {
  v (mV)
  gca (S/cm2)
  ica (mA/cm2)
}

INITIAL {
  m = 0.02
  h = 0.85
}

BREAKPOINT {
  SOLVE states METHOD cnexp
  gca = pbar * (m^2) * h
  ica = gca * (v - eca)
}

DERIVATIVE states {
  m' = (minf - m) / mtau
  h' = (hinf - h) / htau
}

files.na_fast.mod:
TITLE Cortical Pyramidal Fast Inactivating Sodium Channel

NEURON {
  SUFFIX na_fast
  USEION na READ ena WRITE ina
  RANGE gnabar, gna, ina
  GLOBAL minf, hinf, mtau, htau
}

PARAMETER {
  gnabar = 0.15 (S/cm2) <0, 1e9>
  ena = 55.0 (mV)
}

STATE {
  m
  h
}

ASSIGNED {
  v (mV)
  gna (S/cm2)
  ina (mA/cm2)
}

INITIAL {
  m = 0.04
  h = 0.65
}

BREAKPOINT {
  SOLVE states METHOD cnexp
  gna = gnabar * (m^3) * h
  ina = gna * (v - ena)
}

DERIVATIVE states {
  m' = (minf - m) / mtau
  h' = (hinf - h) / htau
}

files.k_delayed.mod:
TITLE Cortical Pyramidal Delayed Rectifier Potassium Channel

NEURON {
  SUFFIX k_delayed
  USEION k READ ek WRITE ik
  RANGE gkbar, gk, ik
  GLOBAL ninf, ntau
}

PARAMETER {
  gkbar = 0.04 (S/cm2) <0, 1e9>
  ek = -85.0 (mV)
}

STATE {
  n
}

ASSIGNED {
  v (mV)
  gk (S/cm2)
  ik (mA/cm2)
}

INITIAL {
  n = 0.25
}

BREAKPOINT {
  SOLVE states METHOD cnexp
  gk = gkbar * (n^4)
  ik = gk * (v - ek)
}

DERIVATIVE states {
  n' = (ninf - n) / ntau
}

files.km_adapt.mod:
TITLE Muscarinic M-Type Spike Frequency Adaptation Potassium Channel

NEURON {
  SUFFIX km_adapt
  USEION k READ ek WRITE ik
  RANGE gkmbar, gkm, ik
  GLOBAL minf, mtau
}

PARAMETER {
  gkmbar = 0.005 (S/cm2) <0, 1e9>
  ek = -85.0 (mV)
}

STATE {
  m
}

ASSIGNED {
  v (mV)
  gkm (S/cm2)
  ik (mA/cm2)
}

INITIAL {
  m = 0.05
}

BREAKPOINT {
  SOLVE states METHOD cnexp
  gkm = gkmbar * m
  ik = gkm * (v - ek)
}

DERIVATIVE states {
  m' = (minf - m) / mtau
}

files.ca_pump.mod:
TITLE Submembrane Calcium Extrusion Pump Mechanism

NEURON {
  SUFFIX ca_pump
  USEION ca READ ica WRITE cai
  RANGE taur, cainf, depth
}

PARAMETER {
  taur = 80.0 (ms)
  cainf = 0.0001 (mM)
  depth = 0.1 (um)
}

STATE {
  cai (mM)
}

ASSIGNED {
  ica (mA/cm2)
}

INITIAL {
  cai = 0.0001
}

BREAKPOINT {
  SOLVE states METHOD cnexp
  cai = cai
}

DERIVATIVE states {
  cai' = (cainf - cai) / taur
}

