files.cpu_top.v:
// Single-Cycle 16-Bit RISC Core Top-Level Module
module cpu_top (
  input         clk,
  input         rst,
  input  [15:0] instr,
  output reg [15:0] pc,
  output wire [15:0] alu_result,
  output wire   zero_flag
);
  wire [2:0]  opcode;
  wire [1:0]  rd;
  wire [1:0]  rs1;
  wire [1:0]  rs2;
  wire        reg_we;
  wire [15:0] rdata1;
  wire [15:0] rdata2;

  assign opcode = instr[15:13];
  assign rd     = instr[12:11];
  assign rs1    = instr[10:9];
  assign rs2    = instr[8:7];
  assign reg_we = (opcode != 3'b111);

  regfile16 u_rf (
    .clk(clk),
    .rst(rst),
    .we(reg_we),
    .rs1(rs1),
    .rs2(rs2),
    .rd(rd),
    .wdata(alu_result),
    .rdata1(rdata1),
    .rdata2(rdata2)
  );

  alu16 u_alu (
    .a(rdata1),
    .b(rdata2),
    .op(opcode),
    .y(alu_result),
    .zero(zero_flag)
  );

  always @(posedge clk) begin
    if (rst)
      pc <= 16'h0000;
    else
      pc <= pc + 16'h0002;
  end
endmodule

files.alu.v:
// 16-Bit Combinational Arithmetic Logic Unit
module alu16 (
  input  [15:0] a,
  input  [15:0] b,
  input  [2:0]  op,
  output reg [15:0] y,
  output wire   zero
);
  assign zero = (y == 16'h0000);

  always @(*) begin
    case (op)
      3'b000: y = a + b;
      3'b001: y = a - b;
      3'b010: y = a & b;
      3'b011: y = a | b;
      3'b100: y = a ^ b;
      default: y = a;
    endcase
  end
endmodule

files.regfile.v:
// 4x16-Bit Dual-Port Register File
module regfile16 (
  input         clk,
  input         rst,
  input         we,
  input  [1:0]  rs1,
  input  [1:0]  rs2,
  input  [1:0]  rd,
  input  [15:0] wdata,
  output reg [15:0] rdata1,
  output reg [15:0] rdata2
);
  reg [15:0] r0;
  reg [15:0] r1;
  reg [15:0] r2;
  reg [15:0] r3;

  always @(posedge clk) begin
    if (rst) begin
      r0 <= 16'h0000;
      r1 <= 16'h0001;
      r2 <= 16'h0002;
      r3 <= 16'h0003;
    end else if (we) begin
      case (rd)
        2'd0: r0 <= wdata;
        2'd1: r1 <= wdata;
        2'd2: r2 <= wdata;
        2'd3: r3 <= wdata;
        default: r0 <= wdata;
      endcase
    end
  end

  always @(*) begin
    case (rs1)
      2'd0: rdata1 = r0;
      2'd1: rdata1 = r1;
      2'd2: rdata1 = r2;
      2'd3: rdata1 = r3;
      default: rdata1 = 16'h0000;
    endcase
    case (rs2)
      2'd0: rdata2 = r0;
      2'd1: rdata2 = r1;
      2'd2: rdata2 = r2;
      2'd3: rdata2 = r3;
      default: rdata2 = 16'h0000;
    endcase
  end
endmodule

